import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        static final int BASE = 1 << 15;
        static final int MOD = 998244353;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v, MOD);
                }
                p /= 2;
                if (p == 0) break;
                v = multiplyMod(v, v, MOD);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % MOD);
            }
            out.println(res);
        }

        static int[] multiplyMod(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            // Represent polynomials as BigIntegers in base BASE
            BigInteger polyA = toBigInteger(a);
            BigInteger polyB = toBigInteger(b);
            BigInteger product = polyA.multiply(polyB);
            int[] res = new int[need];
            for (int i = 0; i < need; i++) {
                BigInteger[] divAndRem = product.divideAndRemainder(BigInteger.valueOf(BASE));
                res[i] = (int) (divAndRem[1].longValue() % mod);
                product = divAndRem[0];
            }
            // The above extracts coefficients from least significant to most, but our polynomial representation is reversed.
            // Actually toBigInteger puts coefficient[0] as least significant digit, so after multiplication, the least significant digit corresponds to coefficient[0]. So we need to reverse? Let's check.
            // In toBigInteger, we set big = big.multiply(BigInteger.valueOf(BASE)).add(BigInteger.valueOf(coeff[i])) for i from 0 to len-1. So coefficient[0] becomes the least significant digit. After multiplication, the least significant digit of product is coefficient[0] of result. So when we extract using divideAndRemainder, we get coefficients in order from least significant (index 0) to most significant (index need-1). So res[0] gets coefficient[0], etc. That matches.
            // But we need to ensure we extract exactly need coefficients. The product may have more digits (up to need). We iterate need times.
            return res;
        }

        static BigInteger toBigInteger(int[] coeff) {
            BigInteger big = BigInteger.ZERO;
            for (int i = coeff.length - 1; i >= 0; i--) {
                big = big.multiply(BigInteger.valueOf(BASE));
                big = big.add(BigInteger.valueOf(coeff[i] & 0x7FFF)); // only low 15 bits used
            }
            return big;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
